import{_ as s,l,o,c as i,v as a,p as d,x as t,d as c,i as r,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"FlexAttention","description":"","frontmatter":{"title":"FlexAttention","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/flex-attention.md","filePath":"llm/flex-attention.md","lastUpdated":1789023840000}'),m={name:"llm/flex-attention.md"};function A(h,e,_,F,x,f){const n=l("Mermaid");return o(),i("div",null,[e[1]||(e[1]=a(`<h1 id="flexattention" tabindex="-1">FlexAttention <a class="header-anchor" href="#flexattention" aria-label="Permalink to &quot;FlexAttention&quot;">​</a></h1><div class="epigraph"><p>多数注意力变体可以写成对分数矩阵的修改；用几行惯用的 PyTorch，由编译器生成融核，而不是为每种变体手写一份 FlashAttention。</p><footer>—— Dong, Feng, Guessous, Liang, He, Flex Attention, MLSys 2025</footer></div><p><a href="/llm/flashattention">FlashAttention</a> 把 SDPA 融进一个 IO 感知核，也把接口收成少数几种官方变体。滑窗、文档掩码、ALiBi、softcap、PagedAttention，以及它们的组合，构成组合爆炸：没有核，研究就掉进「软件彩票」。Dong 等人的 FlexAttention 不把变体枚举进 API，而把变体定义成 <code>score_mod</code> 与 <code>mask_mod</code>，在 <code>torch.compile</code> 里注入手写注意力模板。本篇写编程模型，不重写 FA 的分块 softmax；ALiBi 公式见 <a href="/llm/press-alibi">原文笔记</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>注意力变体改的几乎都是 softmax 之前那张分数表：有的把部分位置设为 \\(-\\infty\\)（因果、滑窗、文档、PrefixLM），有的加偏置或非线性（ALiBi、softcap）。手写核要把在线 softmax、反向、解码、GQA 全部再做一遍。通用编译器又很难自动完成「两次 GEMM + 在线 softmax + 反向」这条注意力专用改写。结果是：Mistral 的滑窗、Gemma 2 的 softcap、MPT 的 ALiBi，谁先进了 FA 谁就能训得动。</p><p>组合是第二道墙。PrefixLM 是前缀双向或上因果；滑窗加 ALiBi 是掩码加分数偏置。为每对组合再写核不可扩展。需要一种能嵌套、能布尔组合、还能利用块级全掩码跳过计算的表示。</p><p><span class="marginnote">Flex 论文把 Differential Transformer 列为超出 score_mod 合同的例子：它改的是两路 softmax 再减，不是单张分数表上的点修改。能写进 <code>score_mod</code> 的，仍是「一张 \\(QK^\\top\\)」家族。</span></p><h3 id="掩码为什么要单独成-api" tabindex="-1">掩码为什么要单独成 API <a class="header-anchor" href="#掩码为什么要单独成-api" aria-label="Permalink to &quot;掩码为什么要单独成 API&quot;">​</a></h3><p>任何 <code>mask_mod</code> 都能写成把分数乘 0/1 的 <code>score_mod</code>，但那样会真的去算被屏蔽的点，并且丢掉「整块可跳过」的语义。独立的布尔掩码让编译器生成 BlockMask：以 tile 为单位标记全掩 / 部分掩 / 全保留。全掩块不加载；部分掩块仍用逐点 <code>mask_mod</code> 保语义。BlockMask 的索引向量还可以兼做 PagedAttention 的页表映射。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>统一写法：</p> \\[\\mathrm{Flex}(Q,K,V)=\\mathrm{softmax}\\bigl(\\mathrm{mod}(QK^\\top/\\sqrt{d_k})\\bigr)V. \\]<p>用户提供</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki min-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D32F2F;">def</span><span style="color:#6F42C1;"> mask_mod</span><span style="color:#24292EFF;">(</span><span style="color:#FF9800;">b</span><span style="color:#212121;">,</span><span style="color:#FF9800;"> h</span><span style="color:#212121;">,</span><span style="color:#FF9800;"> q_idx</span><span style="color:#212121;">,</span><span style="color:#FF9800;"> kv_idx</span><span style="color:#24292EFF;">) </span><span style="color:#212121;">-&gt;</span><span style="color:#1976D2;"> bool</span></span>
<span class="line"><span style="color:#D32F2F;">def</span><span style="color:#6F42C1;"> score_mod</span><span style="color:#212121;">(score, b, h, q_idx, kv_idx)</span><span style="color:#24292EFF;"> -&gt; Tensor</span></span></code></pre></div><p>因果是 <code>q_idx &gt;= kv_idx</code>；滑窗再加距离上限；文档掩码比较 <code>doc_id[q_idx]==doc_id[kv_idx]</code>；ALiBi 是 <code>score + slope[h]*(q_idx-kv_idx)</code>。<code>and_mask</code> / <code>or_mask</code> 组合布尔函数，PrefixLM 就是前缀全连接或上因果。PyTorch API 在 <code>torch.nn.attention.flex_attention</code>：<code>flex_attention(q,k,v,score_mod=...,block_mask=...)</code>，GQA 用 <code>enable_gqa=True</code>。</p><p>降低过程：TorchDynamo 抓住小型 mod 图，TorchInductor 生成 Triton 片段，注入前向 / 反向 / 解码三份手写模板。模板里已有在线 softmax、分块、GQA。反向由 autograd 对 mod 图生成，不必手写每种变体的 VJP。<code>create_block_mask</code> 用 <code>vmap</code> 从 <code>mask_mod</code> 预计算块稀疏表。</p>`,16)),(o(),d(p,null,{default:t(()=>[r(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22score_mod%20%2F%20mask_mod%22%5D%20--%3E%20DY%5B%22TorchDynamo%20%E5%B0%8F%E5%9B%BE%22%5D%0A%20%20DY%20--%3E%20IN%5B%22Inductor%20%E7%94%9F%E6%88%90%20Triton%20%E7%89%87%E6%AE%B5%22%5D%0A%20%20IN%20--%3E%20T%5B%22FA%20%E9%A3%8E%E6%A0%BC%E6%A8%A1%E6%9D%BF%EF%BC%9A%E5%89%8D%E5%90%91%20%2F%20%E5%8F%8D%E5%90%91%20%2F%20%E8%A7%A3%E7%A0%81%22%5D%0A%20%20M%5B%22BlockMask%20%E5%9D%97%E7%A8%80%E7%96%8F%22%5D%20--%3E%20T%0A%20%20QKV%5B%22Q%20K%20V%22%5D%20--%3E%20T%0A%20%20T%20--%3E%20O%5B%22%E8%9E%8D%E6%A0%B8%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="软件彩票被平移到编译缓存" tabindex="-1">软件彩票被平移到编译缓存 <a class="header-anchor" href="#软件彩票被平移到编译缓存" aria-label="Permalink to &quot;软件彩票被平移到编译缓存&quot;">​</a></h3><p>灵活性的代价是：mod 闭包里的 Python 对象若被当成编译常量，稍微改窗口长度就会重编译。官方实践是把运行期变量（偏移、页表）做成 CUDA 张量传入，避免图断裂。第一次 <code>torch.compile</code> 有开销；稳定后的核，论文报在常见变体上达到 FA2 的约 0.68×–1.43×，解码相对 FAKV 约 0.93×–1.45×。gpt-fast 里 16K 上下文端到端约 2.04×；torchtune 训练约 2.4×。这些数字是相对未融合或未特化路径，不是宣称全面超过 FA3 手工核。</p><p>PagedAttention 把 KV 放在非连续页上。Flex 用 BlockMask 当间接表，论文称额外开销可忽略。这比在 FA 上再维护一份分页 fork 更接近「同一编程模型」。</p><p><span class="marginnote">BlockMask 的粒度是注意力 tile，不是 token。窗口大小与块大小不对齐时，边缘块永远是「部分掩」，稀疏收益变薄。选窗长应同时考虑语义与 tile。</span></p><h3 id="组合爆炸变成函数组合" tabindex="-1">组合爆炸变成函数组合 <a class="header-anchor" href="#组合爆炸变成函数组合" aria-label="Permalink to &quot;组合爆炸变成函数组合&quot;">​</a></h3><p>嵌套 <code>score_mod</code> 与布尔掩码让「滑窗 + ALiBi + 文档」不再是新核名。这是对研究迭代的真实帮助：变体的墙钟差不再主导是否做实验。它不能表达换状态更新规则的层（DeltaNet、Mamba），也不能表达两路差分注意力。边界就是 SDPA 的代数：仍是一张分数、一次 softmax、一次加权值。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>原型特性：API 仍可能改（<code>return_lse</code> 已转向 <code>return_aux</code>）。性能随 GPU 代数与 Triton 版本变；相对 FA3 在 Hopper 上手调的核，Flex 通常是「够用且可组合」，不是绝对最快。动态形状、极度不规则的掩码会让 BlockMask 变稠，退回接近稠密 FA。<code>score_mod</code> 过重（大 MLP 打分）会撑爆融合预算，那是 indexer 类设计，应走 DSA 一类专用路径，而不是塞进点修改。</p><p>训练与解码是不同模板。只在训练图里 compile，服务期仍可能落到 SDPA。页式推理要同时提供 BlockMask 与正确的 KV 布局，缺一就静默变慢。不要在没有 <code>torch.compile</code> 的 eager 路径上谈 Flex 的加速——那只是正确性参考。</p><p>与 <a href="/llm/sageattention">SageAttention</a> 等量化注意力也不是替代：Flex 改的是分数定义与掩码，Sage 改的是低比特 GEMM。可以组合，但要各自验证数值。</p><p>研究迭代里，Flex 的真实价值是把「先写核还是先做实验」换成「先写四行 Python」。Neighborhood Attention、文档打包、软封顶，都可以在同一套反向与解码模板上跑通，不必等 FA 仓库接受 PR。组合掩码（因果且滑窗且同文档）若用手写，分支与索引会迅速不可维护；<code>and_mask</code> 把逻辑留在 Python 侧，核侧仍是同一套 BlockMask。代价是调试从 CUDA 挪到编译图：第一次跑慢、错误信息经过 Inductor，需要用小形状先验证 <code>mask_mod</code> 是否与朴素 <code>triu</code> 一致，再放大到训练。</p><p>解码模板（FlexDecoding）针对单查询、长 KV，和训练时 \\(Q\\) 与 \\(KV\\) 等长不是同一占用。报 16K 上相对 SDPA 的 2.04×，分母是 gpt-fast 路径上的 SDPA，不是 FA3。70B 级、短上下文上加速可能接近 1，因为核启动盖过稀疏与融合收益。选型规则与 FA 相同：先看长度与是否自定义掩码，再看是否值得支付编译复杂度。</p><p><span class="marginnote">评测必须声明变体是否已有手工核。对 FA 已支持的因果注意力，Flex 的目标是持平附近；对 FA 不支持的组合，对照应是 SDPA 或未融合实现，否则「2×」没有分母。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FlexAttention 把注意力变体收成 <code>score_mod</code> 与 <code>mask_mod</code>，编译进 FA 风格模板。</li><li>BlockMask 用块级稀疏跳过全掩 tile，并可用于 PagedAttention 映射。</li><li>布尔组合与嵌套修改用来消化变体的组合爆炸。</li><li>在已支持变体上接近 FA2；在 gpt-fast 16K 等端到端设定上相对 SDPA 路径可到约 2×。</li><li>合同限于单张分数表上的 SDPA 家族，不含差分注意力或线性状态层。</li><li>运行期参数应走张量，避免无谓重编译；加速数字绑定 <code>torch.compile</code> 后的核。</li><li>出处：Dong et al.，<em>Flex Attention: a Programming Model for Generating Optimized Attention Kernels</em>，MLSys 2025，arXiv:2412.05496。</li></ul>',16))])}const u=s(m,[["render",A]]);export{P as __pageData,u as default};
